using NuevoAvatar.Periodo.Nuevo.Entities;using NuevoAvatar.Periodo.Nuevo.Repository;using NuevoAvatar.Periodo.Nuevo.Services;using Xunit;
public class PeriodoReglasTest{
[Fact]public void EstadoSeDerivaDeFechas(){var hoy=DateTime.Today;Assert.Equal("ACTIVO",new PeriodoRequest{FechaInicio=hoy,FechaFin=hoy}.Estado);Assert.Equal("FUTURO",new PeriodoRequest{FechaInicio=hoy.AddDays(1),FechaFin=hoy.AddDays(2)}.Estado);Assert.Equal("CERRADO",new PeriodoRequest{FechaInicio=hoy.AddDays(-2),FechaFin=hoy.AddDays(-1)}.Estado);}
[Fact]public async Task DuplicadoProduceConflicto(){var repo=new Repo{Duplicado=true};var s=new PeriodoService(repo,new PeriodoValidator());await Assert.ThrowsAsync<PeriodoConflictoException>(()=>s.CrearAsync(new PeriodoRequest{Anio=2026,NumeroPeriodo=1,FechaInicio=new(2026,1,1),FechaFin=new(2026,2,1)}));}
[Fact]public async Task ProtegeContraEscriturasConcurrentesConSolapamiento(){var repo=new RepoMemoria();var s=new PeriodoService(repo,new PeriodoValidator());var p1=new PeriodoRequest{Anio=2026,NumeroPeriodo=1,FechaInicio=new(2026,1,1),FechaFin=new(2026,4,30)};var p2=new PeriodoRequest{Anio=2026,NumeroPeriodo=2,FechaInicio=new(2026,4,30),FechaFin=new(2026,8,31)};var tareas=await Task.WhenAll(Intentar(s,p1),Intentar(s,p2));Assert.Equal(1,tareas.Count(x=>x));Assert.Single(repo.Items);}
static async Task<bool> Intentar(PeriodoService s,PeriodoRequest r){try{await s.CrearAsync(r);return true;}catch(PeriodoConflictoException){return false;}}
sealed class Repo:IPeriodoRepository{public bool Duplicado;public Task<bool> ExisteDuplicadoAsync(short a,byte n,int?e=null)=>Task.FromResult(Duplicado);public Task<bool> ExisteSolapamientoAsync(short a,DateTime i,DateTime f,int?e=null)=>Task.FromResult(false);public Task<IEnumerable<PeriodoRequest>> ObtenerTodosAsync()=>Task.FromResult<IEnumerable<PeriodoRequest>>([]);public Task<PeriodoRequest?> ObtenerPorIdAsync(int id)=>Task.FromResult<PeriodoRequest?>(null);public Task<int> CrearAsync(PeriodoRequest r)=>Task.FromResult(1);public Task<bool> ModificarAsync(int id,PeriodoRequest r)=>Task.FromResult(true);public Task<bool> EliminarAsync(int id)=>Task.FromResult(true);}
sealed class RepoMemoria:IPeriodoRepository{public List<PeriodoRequest> Items{get;}=[];public async Task<bool> ExisteDuplicadoAsync(short a,byte n,int?e=null){await Task.Delay(15);return Items.Any(x=>x.Anio==a&&x.NumeroPeriodo==n&&x.PeriodoId!=e);}public async Task<bool> ExisteSolapamientoAsync(short a,DateTime i,DateTime f,int?e=null){await Task.Delay(15);return Items.Any(x=>x.Anio==a&&x.FechaInicio<=f&&x.FechaFin>=i&&x.PeriodoId!=e);}public Task<IEnumerable<PeriodoRequest>> ObtenerTodosAsync()=>Task.FromResult<IEnumerable<PeriodoRequest>>(Items);public Task<PeriodoRequest?> ObtenerPorIdAsync(int id)=>Task.FromResult(Items.FirstOrDefault(x=>x.PeriodoId==id));public Task<int> CrearAsync(PeriodoRequest r){r.PeriodoId=Items.Count+1;Items.Add(r);return Task.FromResult(r.PeriodoId);}public Task<bool> ModificarAsync(int id,PeriodoRequest r)=>Task.FromResult(true);public Task<bool> EliminarAsync(int id)=>Task.FromResult(true);}}
